/* Types */
/**  增量追加结果：新增与跳过计数（跳过含子目录、非图片与隐藏项）。 */
export type AppendOutcome = {
	/**  实际拷贝并编号的图片数。 */
	added: number,
	/**  跳过数：子目录按其下文件数计，其余按项计。 */
	skipped: number,
};

/**  构建文件内容：二进制回 `None`，前端展示不支持预览提示。 */
export type BuildFileContent = {
	/**  文本内容；二进制为 `None`。 */
	content: string | null,
	/**  是否可编辑保存。 */
	editable: boolean,
	/**  是否可格式化（可编辑文件 + `container.xml`，后者只读、仅内存格式化）。 */
	formattable: boolean,
};

/**  构建文件树节点：`children` 为 `Some` 即目录（不可编辑），`None` 即文件。 */
export type BuildFileNode = {
	/**  显示名（文件含扩展名）。 */
	name: string,
	/**  构建根起的相对路径（POSIX 分隔）。 */
	path: string,
	/**  是否可编辑保存：固定文件与二进制为假。 */
	editable: boolean,
	/**  子节点；目录为 `Some`，文件为 `None`。 */
	children: BuildFileNode[] | null,
};

/**  构建图片信息：绝对路径供前端转 `asset:`，大小供标题栏展示。 */
export type BuildImageInfo = {
	/**  图片绝对路径。 */
	path: string,
	/**  图片字节数（`u32` 以满足 specta 导出约束，上限内足够）。 */
	size_bytes: number,
};

/**  构建结果：文件树根节点清单与文件总数。 */
export type BuildOutcome = {
	/**  构建根下的顶层节点（已排序，目录在前）。 */
	files: BuildFileNode[],
	/**  全部文件数（不计目录）。 */
	file_count: number,
};

/**  构建标题选项：卷章标题格式 + 章编号方式（复用 TXT 标题模板引擎）；`build/` 落盘用。 */
export type BuildTitleOptions = {
	/**  章标题格式。 */
	chapter_kind: TxtTitleKind,
	/**  章自定义模板；非 `custom` 时忽略。 */
	chapter_pattern: string,
	/**  卷标题格式。 */
	volume_kind: TxtTitleKind,
	/**  卷自定义模板；非 `custom` 时忽略。 */
	volume_pattern: string,
	/**  章编号方式。 */
	chapter_numbering: ChapterNumbering,
};

/**  单章正文：编辑页中栏的读写单位；标题只读展示，正文按行往返。 */
export type ChapterContent = {
	/**  章完整标题（只读展示用）。 */
	full_title: string,
	/**  章正文：每元素一行（与解析口径一致：去首尾空白、无空行）。 */
	lines: string[],
};

/**  单章命中汇总：下标与大纲数组同源。 */
export type ChapterMatches = {
	/**  卷下标。 */
	volume_index: number,
	/**  章下标。 */
	chapter_index: number,
	/**  命中行（按行号升序）。 */
	matches: LineMatch[],
};

/**  章编号方式：分卷书章标题渲染时的编号口径；平铺书两种等价。 */
export type ChapterNumbering = 
/**  跨卷连续：文档顺序全局序号，忽略解析号。 */
"continuous" | 
/**  分卷重置：解析出的卷内号（现状口径）。 */
"per_volume";

/**  章大纲：右栏识别结果的只读条目，字数仅计章正文。 */
export type ChapterOutline = {
	/**  章完整标题。 */
	title: string,
	/**  本章正文字数（`lines` 字符数之和）。 */
	chars: number,
};

/**  垃圾清理预设：只读扫描用的内置模式；手机号这类高误伤项刻意不收录，只做标出。 */
export type CleanupPreset = 
/**  完整网址：`http(s)://` 锚定，`v2.0` 这类不算。 */
"UrlFull" | 
/**  站点域名：`www.` 或常见后缀裸域名。 */
"UrlDomain" | 
/**  首发更新：转载站的首发、追更话术。 */
"PromoRelease" | 
/**  站点名称：转载站站名与阅读引导。 */
"PromoSite" | 
/**  求票订阅：互动求票与订阅话术。 */
"PromoVote" | 
/**  社群引流：书友群、加群话术。 */
"PromoGroup" | 
/**  QQ 号码：`QQ` + 5–12 位数字。 */
"ContactQq" | 
/**  微信号码：`微信(号)` + 字母开头 ID。 */
"ContactWechat" | 
/**  群组号码：`群(号)` + 数字。 */
"ContactGroup";

/**  关闭窗口行为：落盘值为 `snake_case` 字符串，未知一律回落弹窗提示 */
export type CloseBehavior = "prompt" | "exit" | "minimize_to_tray";

/**
 *  压缩状态探针：供切回页面时回填进度；从未开始返回空闲零值。
 *  `has_backup` 供工具条“撤销/清除备份”按钮显隐，与进度无关、每次探针实时计算。
 */
export type ComicCompressStatus = {
	running: boolean,
	done_files: number,
	total_files: number,
	has_backup: boolean,
};

/**  转换状态探针：供切回页面时回填进度；从未开始返回空闲零值。 */
export type ComicConvertStatus = {
	running: boolean,
	done_files: number,
	total_files: number,
};

/**  漫画导出勾选：EPUB / PDF / 原图 / 封面。 */
export type ComicExportItems = {
	/**  EPUB 电子书。 */
	epub: boolean,
	/**  单个 PDF 文件。 */
	pdf: boolean,
	/**  原图（文件夹或压缩包，见 `ComicImagesMode`）。 */
	images: boolean,
	/**  封面图片。 */
	cover: boolean,
};

/**  导出作业状态：供切回页面时回填进度；从未开始返回空闲零值。 */
export type ComicExportState = {
	running: boolean,
	done_units: number,
	total_units: number,
};

/**  漫画导出状态：进页一次查全，前端据此渲染表单与禁用态。 */
export type ComicExportStatus = {
	/**  是否有可导出的解析产物。 */
	has_content: boolean,
	/**  话数。 */
	volume_count: number,
	/**  图片总页数。 */
	page_count: number,
	/**  图片总字节数（`u32` 以满足 specta 导出约束，上限内足够）。 */
	total_bytes: number,
	/**  是否有可导出的打包产物。 */
	has_epub: boolean,
	/**  打包文件名；无产物时为 `None`。 */
	epub_name: string | null,
	/**  是否有可导出的封面。 */
	has_cover: boolean,
	/**  封面扩展名（小写）；无封面时为 `None`。 */
	cover_ext: string | null,
	/**  项目名。 */
	project_name: string,
	/**  书名。 */
	book_title: string,
};

/**  漫画图片信息：绝对路径供前端转 `asset:`，大小供标题栏展示。 */
export type ComicImageInfo = {
	/**  图片绝对路径。 */
	path: string,
	/**  图片字节数（`u32` 以满足 specta 导出约束，上限内足够）。 */
	size_bytes: number,
};

/**  原图导出形态：文件夹 mirror 落盘，或打成单个压缩包。 */
export type ComicImagesMode = 
/**  文件夹：`dest/<命名>/` 下按话建子目录。 */
"folder" | 
/**  压缩包：`dest/<命名>.zip`，包内与文件夹模式同结构。 */
"zip";

/**  漫画原稿状态：左栏文件卡片的只读展示；缺目录时 `exists` 为假。 */
export type ComicImagesStatus = {
	/**  `sources/images` 是否存在且含有效图片。 */
	exists: boolean,
	/**  话数：平铺为 1（含收纳话在内按实际话计数）。 */
	volume_count: number,
	/**  图片总页数。 */
	page_count: number,
	/**  图片总字节数（`u32` 以满足 specta 导出约束，上限内足够）。 */
	size_bytes: number,
	/**  原稿更新时间（UTC `RFC3339`，取目录 mtime）；不存在时为 `None`。 */
	updated_at: string | null,
};

/**  漫画组织形态：平铺单话，或按子目录分话。 */
export type ComicMode = "flat" | "volumes";

/**
 *  孤儿图片扫描结果：`content.json` 未引用、但落在 `sources/images/` 下的图片；
 *  封面在 `sources/` 根目录天然排除，隐藏文件与导入元信息不计入。
 */
export type ComicOrphans = {
	/**  孤儿相对路径（POSIX），自然排序。 */
	paths: string[],
	/**  孤儿总字节数（`u32` 以满足 specta 导出约束，上限内足够）。 */
	total_bytes: number,
};

/**  解析大纲：右栏识别结果的只读展示，图片二进制不出 IPC，只出清单。 */
export type ComicOutline = {
	/**  组织形态。 */
	mode: ComicMode,
	/**  话数。 */
	volume_count: number,
	/**  图片总页数。 */
	page_count: number,
	/**  图片总字节数。 */
	total_bytes: number,
	/**  复制与解析时跳过的无效文件数：导入元信息记账 + 落盘扫描合并，展示用。 */
	ignored_count: number,
	/**  话页树（已排序）。 */
	volumes: ComicVolumeOutline[],
};

/**  单页大纲：右栏识别结果的只读条目。 */
export type ComicPageOutline = {
	/**  相对 `images/` 的路径（POSIX 分隔，前端取图用）。 */
	path: string,
	/**  本页字节数（`u32` 以满足 specta 导出约束，上限内足够）。 */
	size_bytes: number,
};

/**  图片在 PDF 页面内的填充方式。 */
export type ComicPdfFillMode = 
/**  保持比例并完整显示图片。 */
"contain" | 
/**  保持比例并裁切超出页面的部分。 */
"cover" | 
/**  分别缩放宽高以填满页面。 */
"stretch";

/**  图片的水平对齐位置。 */
export type ComicPdfHorizontalAlignment = 
/**  左对齐。 */
"left" | 
/**  水平居中。 */
"center" | 
/**  右对齐。 */
"right";

/**  漫画 PDF 导出参数；固定尺寸字段仅在固定模式下使用，原图尺寸模式下填充与对齐无意义。 */
export type ComicPdfOptions = {
	/**  页面尺寸来源。 */
	page_size: ComicPdfPageSize,
	/**  固定页面宽度（像素）。 */
	width_px: number,
	/**  固定页面高度（像素）。 */
	height_px: number,
	/**  像素到 PDF 物理页面的换算分辨率。 */
	dpi: number,
	/**  图片填充方式。 */
	fill_mode: ComicPdfFillMode,
	/**  图片水平对齐。 */
	horizontal_alignment: ComicPdfHorizontalAlignment,
	/**  图片垂直对齐。 */
	vertical_alignment: ComicPdfVerticalAlignment,
	/**  是否将项目封面作为第一页。 */
	include_cover: boolean,
	/**  话标题格式：多话 PDF 书签的卷标题渲染口径，与原图话目录同源。 */
	volume_kind: TxtTitleKind,
	/**  话标题自定义模板：`volume_kind` 为自定义时生效。 */
	volume_pattern: string,
	/**  写入文档元数据：为空即关闭；非空时按所选字段写入 Info（为空跳过）。 */
	metadata: MetadataField[],
};

/**  PDF 页面尺寸来源。 */
export type ComicPdfPageSize = 
/**  按漫画页的平均像素宽高生成统一画布。 */
"average" | 
/**  使用用户指定的像素宽高生成统一画布。 */
"fixed" | 
/**  每页采用原图宽高，一图一页；填充与对齐此时无意义。 */
"original";

/**  图片的垂直对齐位置。 */
export type ComicPdfVerticalAlignment = 
/**  顶部对齐。 */
"top" | 
/**  垂直居中。 */
"center" | 
/**  底部对齐。 */
"bottom";

/**  尺寸调整状态探针：供切回页面时回填进度；从未开始返回空闲零值。 */
export type ComicResizeStatus = {
	running: boolean,
	done_files: number,
	total_files: number,
	/**  是否有可撤销的备份（与压缩共用备份目录）。 */
	has_backup: boolean,
};

/**  话输入：编辑页全量提交的单话（标题可改、话可增删排序，页须全量覆盖）。 */
export type ComicVolumeInput = {
	/**  话标题；`None` 仅允许单话（平铺保持无标题）。 */
	title: string | null,
	/**  话内有序路径（相对 `images/` 的 POSIX 路径）。 */
	pages: string[],
};

/**  话大纲：右栏识别结果的只读条目。 */
export type ComicVolumeOutline = {
	/**  话标题；平铺无标题话为 `None`，前端回落“未分话”。 */
	title: string | null,
	/**  话内页面（含路径与字节数）。 */
	pages: ComicPageOutline[],
};

/**
 *  命令统一返回的错误类型。
 * 
 *  `serde` 表示即前端契约：序列化为 `{ kind, message }`，前端 `.failed()` 回调按此形状收参。
 */
export type CommandError = 
/**  内部错误（`anyhow` 的链式上下文会展开成可读文本） */
{ kind: "Internal"; message: string } | 
/**  用户取消：长时间作业在文件边界处中断，非失败，前端据此静默或轻提示。 */
{ kind: "Cancelled"; message: string };

/**  压缩参数：原地重编码，保持源格式与路径不变。 */
export type CompressOptions = {
	/**  缩放比例（相对当前尺寸等比），25-100，100 为不缩放。 */
	scale_percent: number,
	/**  灰度转换开关；已灰度图在无需缩放时跳过。 */
	grayscale: boolean,
	/**  JPEG/WebP 有损质量，1-100。 */
	quality: number,
	/**  WebP 无损开关（开则忽略质量）。 */
	webp_lossless: boolean,
	/**  PNG 压缩级别，0-9。 */
	png_level: number,
};

/**  压缩结果：原地覆盖后的大纲 + 何度跳过剩下的灰度。 */
export type CompressOutcome = {
	outline: ComicOutline,
	processed: number,
	skipped: number,
};

/**  压缩预览：只读 `content.json` + 文件大小，不解码图片。 */
export type CompressPreview = {
	total: number,
	total_bytes: number,
};

/**
 *  应用完整配置：各持久化项聚合于此，`store` 内仍按扁平键（`KEY_*`）逐项存储。
 *  新增字段必须能 `Default`（否则旧文件缺键会解析失败）；写路径统一走 `apply_patch` 逐键写入，
 *  禁止用陈旧的 `Config` 整体覆盖。
 * 
 *  新增一个配置项的固定步骤：
 *  `KEY_*` 常量 → 本结构体加字段 → `ConfigPatch` 加同名 `Option` 字段 → `load_config` 回填
 *  → 需要运行时副作用则加进 `apply_runtime_effects` → `reset_patch` 补默认值
 *  → 需跨键规整（如托盘关闭时禁最小化）则加进 `coerce_patch` → `cargo test` 重生成绑定。
 * 
 *  只有**改动已有字段的语义或位置**时才需要递增 `CURRENT_SCHEMA_VERSION` 并在 `MIGRATIONS`
 *  末尾补一级迁移，否则老用户配置会静默失效（纯新增字段由 `Default` + 容错读取兜住）。
 *  布尔开关天然扁平并存（与 `store` 扁平键一一对应），不为 lint 拆结构。
 */
export type Config = Config_Serialize | Config_Deserialize;

/**  局部更新补丁：字段缺省或为 `null` 均表示"不改该键"，非 `null` 表示写入该值 */
export type ConfigPatch = {
	/**  界面语言 */
	locale?: Locale | null,
	/**  开机自启 */
	auto_start?: boolean | null,
	/**  记住窗口状态 */
	remember_window?: boolean | null,
	/**  自动检查更新 */
	auto_check_update?: boolean | null,
	/**  系统托盘开关 */
	tray_enabled?: boolean | null,
	/**  关闭窗口行为 */
	close_behavior?: CloseBehavior | null,
	/**  显示应用的全局快捷键：`None`（或缺省 / `null`）表示不改该键 */
	shortcut_show?: string | null,
};

/**
 *  应用完整配置：各持久化项聚合于此，`store` 内仍按扁平键（`KEY_*`）逐项存储。
 *  新增字段必须能 `Default`（否则旧文件缺键会解析失败）；写路径统一走 `apply_patch` 逐键写入，
 *  禁止用陈旧的 `Config` 整体覆盖。
 * 
 *  新增一个配置项的固定步骤：
 *  `KEY_*` 常量 → 本结构体加字段 → `ConfigPatch` 加同名 `Option` 字段 → `load_config` 回填
 *  → 需要运行时副作用则加进 `apply_runtime_effects` → `reset_patch` 补默认值
 *  → 需跨键规整（如托盘关闭时禁最小化）则加进 `coerce_patch` → `cargo test` 重生成绑定。
 * 
 *  只有**改动已有字段的语义或位置**时才需要递增 `CURRENT_SCHEMA_VERSION` 并在 `MIGRATIONS`
 *  末尾补一级迁移，否则老用户配置会静默失效（纯新增字段由 `Default` + 容错读取兜住）。
 *  布尔开关天然扁平并存（与 `store` 扁平键一一对应），不为 lint 拆结构。
 */
export type Config_Deserialize = {
	/**  配置结构版本：旧文件缺键时回落 `0`，任何写入都会带上当前版本号 */
	schema_version?: number,
	/**  界面语言：缺失、类型不符或无法识别时回落默认值，绝不让整包解析失败 */
	locale?: Locale,
	/**  开机自启：缺失或类型不符时回落 `false`，绝不让整包解析失败 */
	auto_start?: boolean,
	/**  记住窗口状态：缺失或类型不符时回落 `false`，绝不让整包解析失败 */
	remember_window?: boolean,
	/**  自动检查更新：缺失或类型不符时回落 `false`，绝不让整包解析失败 */
	auto_check_update?: boolean,
	/**  系统托盘开关：缺失或类型不符时回落默认值（`true`），绝不让整包解析失败 */
	tray_enabled?: boolean,
	/**  关闭窗口行为：缺失、类型不符或无法识别时回落弹窗提示，绝不让整包解析失败 */
	close_behavior?: CloseBehavior,
	/**
	 *  显示应用的全局快捷键：`Ctrl+Shift+S` 风格，空字符串表示未设置；
	 *  缺失、类型不符或纯空白时回落空字符串，绝不让整包解析失败
	 */
	shortcut_show?: string,
};

/**
 *  应用完整配置：各持久化项聚合于此，`store` 内仍按扁平键（`KEY_*`）逐项存储。
 *  新增字段必须能 `Default`（否则旧文件缺键会解析失败）；写路径统一走 `apply_patch` 逐键写入，
 *  禁止用陈旧的 `Config` 整体覆盖。
 * 
 *  新增一个配置项的固定步骤：
 *  `KEY_*` 常量 → 本结构体加字段 → `ConfigPatch` 加同名 `Option` 字段 → `load_config` 回填
 *  → 需要运行时副作用则加进 `apply_runtime_effects` → `reset_patch` 补默认值
 *  → 需跨键规整（如托盘关闭时禁最小化）则加进 `coerce_patch` → `cargo test` 重生成绑定。
 * 
 *  只有**改动已有字段的语义或位置**时才需要递增 `CURRENT_SCHEMA_VERSION` 并在 `MIGRATIONS`
 *  末尾补一级迁移，否则老用户配置会静默失效（纯新增字段由 `Default` + 容错读取兜住）。
 *  布尔开关天然扁平并存（与 `store` 扁平键一一对应），不为 lint 拆结构。
 */
export type Config_Serialize = {
	/**  配置结构版本：旧文件缺键时回落 `0`，任何写入都会带上当前版本号 */
	schema_version: number,
	/**  界面语言：缺失、类型不符或无法识别时回落默认值，绝不让整包解析失败 */
	locale: Locale,
	/**  开机自启：缺失或类型不符时回落 `false`，绝不让整包解析失败 */
	auto_start: boolean,
	/**  记住窗口状态：缺失或类型不符时回落 `false`，绝不让整包解析失败 */
	remember_window: boolean,
	/**  自动检查更新：缺失或类型不符时回落 `false`，绝不让整包解析失败 */
	auto_check_update: boolean,
	/**  系统托盘开关：缺失或类型不符时回落默认值（`true`），绝不让整包解析失败 */
	tray_enabled: boolean,
	/**  关闭窗口行为：缺失、类型不符或无法识别时回落弹窗提示，绝不让整包解析失败 */
	close_behavior: CloseBehavior,
	/**
	 *  显示应用的全局快捷键：`Ctrl+Shift+S` 风格，空字符串表示未设置；
	 *  缺失、类型不符或纯空白时回落空字符串，绝不让整包解析失败
	 */
	shortcut_show: string,
};

/**  解析问题条目：卷/章均存完整行，前端定位与组装文案用。 */
export type ContentIssue = {
	/**  问题种类。 */
	kind: IssueKind,
	/**  所属卷完整行；卷级问题即该卷本身，全局断号时为 `None`。 */
	volume: string | null,
	/**  所属章完整行；卷级问题为 `None`。 */
	chapter: string | null,
	/**  相关编号：重复/缺失的编号值；空缺类为 `None`。 */
	number: number | null,
};

/**
 *  解析产物摘要：存在性之外的展示信息。
 * 
 *  字段名与 `ParseOutline` 同口径（`struct_field_names` 豁免）。
 */
export type ContentSummary = {
	/**  卷数（含无标题卷）。 */
	volume_count: number,
	/**  全书章节总数。 */
	chapter_count: number,
	/**  正文字数：仅各章 `lines` 字符数之和（不计换行符）。 */
	char_count: number,
};

/**  转换参数：随目标格式生效其余忽略（前端按格式切换控件）。 */
export type ConvertOptions = {
	/**  JPEG/WebP 有损质量，1-100。 */
	quality: number,
	/**  WebP 无损开关（开则忽略质量）。 */
	webp_lossless: boolean,
	/**  PNG 压缩级别，0-9。 */
	png_level: number,
	/**  同格式也重编码（默认关 = 跳过，幂等）。 */
	force: boolean,
};

/**  转换预览：落点确认弹窗按行展示。 */
export type ConvertPreview = {
	items: ConvertPreviewItem[],
	total: number,
};

/**  预览行：某源格式的待转张数。 */
export type ConvertPreviewItem = {
	/**  小写源扩展名（`jpeg` 归一为 `jpg`）。 */
	from: string,
	count: number,
};

/**  导出勾选项：全假直接报错，至少选一项。 */
export type ExportItems = {
	/**  导出 EPUB。 */
	epub: boolean,
	/**  导出标准 TXT。 */
	txt: boolean,
	/**  导出封面。 */
	cover: boolean,
};

/**  命名来源：项目名 / 书名 / 自定义。 */
export type ExportNaming = 
/**  用项目名。 */
"project" | 
/**  用书名。 */
"book" | 
/**  用用户填写的自定义名。 */
"custom";

/**  导出结果：最终目录绝对路径 + 落盘文件名清单。 */
export type ExportOutcome = {
	/**  最终目录（`<自选目录>/<命名>/` 绝对路径）。 */
	dir: string,
	/**  落盘文件名（已排序）。 */
	files: string[],
};

/**  导出状态：进页一次查全，前端据此渲染表单与禁用态。 */
export type ExportStatus = {
	/**  是否有可导出的解析产物。 */
	has_content: boolean,
	/**  解析产物摘要；无产物时为 `None`。 */
	content: ContentSummary | null,
	/**  是否有可导出的打包产物。 */
	has_epub: boolean,
	/**  打包文件名；无产物时为 `None`。 */
	epub_name: string | null,
	/**  是否有可导出的封面。 */
	has_cover: boolean,
	/**  封面扩展名（小写）；无封面时为 `None`。 */
	cover_ext: string | null,
	/**  项目名（`project.json`）。 */
	project_name: string,
	/**  书名（`metadata.json`）。 */
	book_title: string,
};

/**  筛选结果：命中章节清单；超限截断时置位，前端 toast 提示。 */
export type FilterOutcome = {
	/**  有命中的章节（文档顺序）。 */
	chapters: ChapterMatches[],
	/**  是否因命中上限截断。 */
	truncated: boolean,
};

/**  批量格式化结果：成功数 + 跳过（`mimetype` 与二进制）+ 失败清单（内容保持原样）。 */
export type FormatOutcome = {
	/**  成功格式化的文件数（含已规范无需改动的）。 */
	formatted: number,
	/**  跳过的文件。 */
	skipped: string[],
	/**  格式化失败的文件。 */
	failed: string[],
};

/**  目标格式：与源格式集合（jpg/jpeg/png/webp）对齐，前端下拉直接用。 */
export type ImageTargetFormat = "jpeg" | "png" | "webp";

/**  问题种类：解析结果的警告项，只做展示，不阻塞解析。 */
export type IssueKind = 
/**  编号空缺：卷/章的 `number` 为 `None`。 */
"MissingNumber" | 
/**  编号重复：同卷内章号重复或全局卷号重复。 */
"DuplicateNumber" | 
/**  缺失章节：卷内章号或全局卷号存在断号。 */
"MissingChapter" | 
/**  标题空缺：纯标题回落为完整行。 */
"MissingTitle";

/**  单行命中：行号为章内 1-based，与编辑器行号同源。 */
export type LineMatch = {
	/**  章内行号（1-based）。 */
	line: number,
	/**  本行全部非重叠命中（空跨度已剔除）。 */
	spans: TextSpan[],
};

/**  应用支持的语言 */
export type Locale = "en" | "zh-CN";

/**  元数据字段：导出勾选源；渲染顺序固定为著录序，与选择顺序无关。 */
export type MetadataField = 
/**  书名。 */
"title" | 
/**  副标题。 */
"alternative" | 
/**  作者。 */
"creator" | 
/**  贡献者。 */
"contributor" | 
/**  语言。 */
"language" | 
/**  出版社。 */
"publisher" | 
/**  系列名。 */
"series" | 
/**  卷次。 */
"volume" | 
/**  出版日期。 */
"date_published" | 
/**  版权。 */
"rights" | 
/**  来源。 */
"source" | 
/**  主题词（多值，`、` 连接）。 */
"subjects" | 
/**  简介（多行，`简介：` 独占首行）。 */
"description";

/**  筛选种类：右栏筛选器的前端契约；关键词、正则、垃圾清理、标点符号、标点闭合五选一。 */
export type NovelFilter = 
/**  关键词含匹配：空关键词前后端都拦截。 */
{ type: "Keyword"; 
/**  关键词原文（大小写不敏感时内部转小写比对，正文索引不受影响）。 */
keyword: string; 
/**  是否区分大小写。 */
case_sensitive: boolean } | 
/**  正则表达式：Rust 正则语法，非法 pattern 直接报错。 */
{ type: "Regex"; 
/**  用户填写的正则原文。 */
pattern: string } | 
/**  垃圾清理：内置预设多选，空预设前后端都拦截。 */
{ type: "Cleanup"; 
/**  启用的预设清单（顺序不敏感，后端按固定优先级编译）。 */
presets: CleanupPreset[] } | 
/**  标点符号：排版问题预设多选，空预设前后端都拦截。 */
{ type: "Punct"; 
/**  启用的预设清单（顺序不敏感，后端按固定优先级编译）。 */
presets: PunctPreset[] } | 
/**  标点闭合：成对标点多选 + 检测范围，空预设前后端都拦截。 */
{ type: "Pairs"; 
/**  启用的成对种类清单（顺序不敏感，栈机统一处理）。 */
pairs: PairKind[]; 
/**  检测范围：按行独立，或跨行延续。 */
scope: PairScope };

/**
 *  导入结果：落盘状态 + 来源编码标签（`UTF-8` / `UTF-16LE` / `UTF-16BE` / `GB18030`），
 *  前端据此提示自动转码，非 UTF-8 来源统一转存为 UTF-8。
 */
export type NovelImportOutcome = {
	/**  导入后的原文状态。 */
	status: NovelTextStatus,
	/**  解码来源原文时实际使用的编码。 */
	encoding: string,
};

/**  小说原文状态：左栏文件卡片的只读展示；缺文件时 `exists` 为假。 */
export type NovelTextStatus = {
	/**  `sources/content.txt` 是否存在。 */
	exists: boolean,
	/**  原文字节数；不存在时为 `0`（`u32` 以满足 specta 导出约束，上限内足够）。 */
	size_bytes: number,
	/**  原文更新时间（UTC `RFC3339`）；不存在或不可读时为 `None`。 */
	updated_at: string | null,
};

/**  打包产物信息：重进页恢复展示的唯一依据。 */
export type PackageInfo = {
	/**  文件名（如 `雾镇.epub`）。 */
	file_name: string,
	/**  产物字节数（`u32` 以满足 specta 导出约束，上限内足够）。 */
	size_bytes: number,
	/**  打包时间（UTC `RFC3339`）。 */
	updated_at: string,
};

/**  打包结果：产物信息 + 紧随其后的自动校验。 */
export type PackageOutcome = {
	/**  产物信息。 */
	package: PackageInfo,
	/**  自动校验结果。 */
	validation: ValidationOutcome,
};

/**  打包阶段：`zip` 打包中（带确定性进度）/ `validate` 校验中（整块调用，无细分）。 */
export type PackageStage = 
/**  打包中。 */
"zip" | 
/**  校验中。 */
"validate";

/**  打包作业状态：供切回页面时回填进度；从未开始返回空闲零值。 */
export type PackagingStatus = {
	running: boolean,
	stage: PackageStage | null,
	done_files: number,
	total_files: number,
};

/**  成对标点种类：只读扫描用的闭合检测模式；ASCII 与全角收进同一叶子，按"对"开关。 */
export type PairKind = 
/**  圆括号对：（）()。 */
"Round" | 
/**  方括号对：［］[]。 */
"Square" | 
/**  花括号对：｛｝{}。 */
"Brace" | 
/**  方头括号：【】。 */
"TortBlack" | 
/**  象形括号：〔〕。 */
"TortWhite" | 
/**  双书名号：《》。 */
"BookDouble" | 
/**  单书名号：〈〉。 */
"BookSingle" | 
/**  双弯引号：“”。 */
"DQuote" | 
/**  单弯引号：‘’。 */
"SQuote" | 
/**  直角单引：「」。 */
"CQuoteS" | 
/**  直角双引：『』。 */
"CQuoteD" | 
/**  英文单引：''（同字符开闭，toggle 语义）。 */
"AsciiS" | 
/**  英文双引：""（同字符开闭，toggle 语义）。 */
"AsciiD" | 
/**  反向双引：〝〞。 */
"RevQuote";

/**  配对检测范围：按行独立，或跨行延续（含多段对话引号识别）。 */
export type PairScope = 
/**  按行筛选：每行独立跑栈机，无豁免。 */
"Line" | 
/**  跨行筛选：状态机跨行，引号行首延续静默吸收。 */
"Chapter";

/**  解析大纲：右栏识别结果的只读展示，正文行不出 IPC。 */
export type ParseOutline = {
	/**  卷数（含无标题卷）。 */
	volume_count: number,
	/**  全书章节总数。 */
	chapter_count: number,
	/**  正文总行数：仅各章 `lines` 之和（前言、卷简介不计）。 */
	line_count: number,
	/**  正文字数：仅各章 `lines` 字符数之和（不计换行符）。 */
	char_count: number,
	/**  前言行数（暂不展示，保留备查）。 */
	preface_lines: number,
	/**  卷章标题树。 */
	volumes: VolumeOutline[],
	/**
	 *  两套正则都没有数字组（第一捕获组）时为真；此时全量编号为 `None`。
	 *  个别数字串不可解析不置位，仅 pattern 级缺组置位。
	 */
	numbers_missing: boolean,
	/**  两套正则都没有标题组（第二捕获组）时为真；此时纯标题全员回落。 */
	titles_missing: boolean,
	/**  解析问题：文档顺序收集，展示用。 */
	issues: ContentIssue[],
	/**
	 *  重排备份是否存在：存在时前端展示“撤销重排”，用完即删；
	 *  重新解析或编辑正文后失效（后端落盘时删备份）。
	 */
	backup_exists: boolean,
	/**  扫描的非空行数：诊断展示用（命中 + 未命中）。 */
	scanned_lines: number,
	/**  疑似标题但两套正则都没命中的行（前 N 个原文）：诊断展示用，正文误伤可接受。 */
	unmatched_samples: string[],
	/**  疑似标题行的全量计数（采样只存前 N 个）。 */
	unmatched_total: number,
};

/**  项目基本信息：`project.json` 的落盘格式即前端契约，时间全链路 UTC。 */
export type ProjectInfo = {
	/**  项目 id，与文件夹名一致（`UUID v4` 字符串） */
	id: string,
	/**  项目展示名，允许重名，不参与路径 */
	name: string,
	/**  项目类型；`type` 是 Rust 关键字，落盘与契约仍用 `type` */
	type: ProjectType,
	/**  创建时间（UTC `RFC3339`） */
	created_at: string,
	/**  更新时间（UTC `RFC3339`，内容编辑时刷新，创建时与创建时间一致） */
	updated_at: string,
};

/**  项目元数据：都柏林核心 + EPUB3 构建所需的著录信息。 */
export type ProjectMetadata = {
	/**  结构版本，固定 `2`，由后端断言。 */
	schema_version: number,
	/**  项目标识符，复用项目 id（`dc:identifier` 取 `urn:uuid:` 前缀），只读。 */
	identifier: string,
	/**  书名（`dc:title`），默认取项目展示名。 */
	title: string,
	/**  副标题（`dc:alternative`）。 */
	alternative: string,
	/**  作者（`dc:creator`）。 */
	creator: string,
	/**  贡献者（`dc:contributor`），单值。 */
	contributor: string,
	/**  语言（`dc:language`，BCP47）；小说固定 `zh-CN`。 */
	language: string,
	/**  出版社（`dc:publisher`）。 */
	publisher: string,
	/**  简介（`dc:description`，兼小说扉页描述块）：每元素一行，已去空去首尾空白。 */
	description: string[],
	/**  主题词（`dc:subject`，可多值）。 */
	subjects: string[],
	/**  出版日期（`dc:date`），`YYYY-MM-DD` 或空。 */
	date_published: string | null,
	/**  版权（`dc:rights`）。 */
	rights: string,
	/**  系列名（EPUB `belongs-to-collection`，`collection-type` 为 `series`）。 */
	series: string,
	/**  卷次（EPUB `group-position`，如 `上` / `3`）。 */
	volume: string,
	/**  来源（`dc:source`，如原著或改编出处）。 */
	source: string,
	/**  封面相对路径（如 `sources/cover.jpg`），只经封面导入命令写入。 */
	cover: string | null,
	/**  更新时间（UTC `RFC3339`），后端每次保存刷新。 */
	updated_at: string,
};

/**  项目概览：详情页的只读快照；无元数据文件或解析失败时回落空，不建文件。 */
export type ProjectOverview = {
	/**  元数据内容；缺失或损坏时为 `None`，前端回落默认展示。 */
	metadata: ProjectMetadata | null,
	/**  封面绝对路径（供前端转 `asset:` 预览）；未设置或文件缺失时为 `None`。 */
	cover_path: string | null,
};

/**  项目总览条目：基本信息 + 四阶段状态 + 内容条数（小说为章数，漫画为页数，未解析为 0）。 */
export type ProjectOverviewItem = {
	info: ProjectInfo,
	stages: ProjectStageStatus,
	content_count: number,
	/**  封面绝对路径（供前端转 `asset:` 预览）；无封面为 `None`。 */
	cover_path: string | null,
};

/**
 *  四阶段状态：素材（已导入）→ 解析（`content.json` 存在）→ 构建（`build/` 存在）→ 打包（`dist/` 有产物）。
 *  四个独立开关即管线本身，布尔是最直接的形状（枚举反而增加前后端转换成本）。
 */
export type ProjectStageStatus = {
	/**  素材已导入（原文 / 原稿存在）。 */
	has_source: boolean,
	/**  已解析（识别大纲存在）。 */
	has_content: boolean,
	/**  有构建产物。 */
	has_build: boolean,
	/**  有打包产物。 */
	has_package: boolean,
};

/**  项目类型：落盘与契约为小写字符串，前后端共用 `"novel" | "comic"`。 */
export type ProjectType = "novel" | "comic";

/**  标点符号预设：只读扫描用的排版问题模式；`……`/`——`恰两连是正确写法，刻意放过。 */
export type PunctPreset = 
/**  半角标点：半角句读括号（含 `.`，`v2.0` 这类会中，find-only 可接受）。 */
"HalfPunct" | 
/**  全角符号：错用的全角（中文正用的，。！？等已排除）。 */
"FullSymbol" | 
/**  零宽字符：零宽空格/连接符与 BOM。 */
"ZeroWidth" | 
/**  特殊空格：不换行空格、全角空格、制表符。 */
"WeirdSpace" | 
/**  特殊符号：Emoji 与装饰符号。 */
"SpecialSym" | 
/**  连续标点：同类标点连发（省略号/破折号 3 连起标，其余 2 连起标）。 */
"RepeatPunct";

/**  完整适配的补底颜色；JPEG 无透明通道，选透明按白色压平（前端明示）。 */
export type ResizeBackground = "white" | "black" | "transparent";

/**  固定画布填充方式：与 PDF 导出同语义。 */
export type ResizeFill = 
/**  等比适配并补底，完整显示。 */
"contain" | 
/**  等比铺满并裁切，无白边。 */
"cover" | 
/**  宽高各拉满，可能变形。 */
"stretch";

/**  尺寸调整方式：目标尺寸的确定口径；百分比模式归压缩所有，此处不提供。 */
export type ResizeMode = 
/**  宽固定为 `width_px`，高按比例。 */
"width" | 
/**  高固定为 `height_px`，宽按比例。 */
"height" | 
/**  最长边固定为 `width_px`（边长复用宽度字段），短边按比例。 */
"long_edge" | 
/**  输出恰为 `width_px` × `height_px`，比例不一致时按 `fill` 处理。 */
"fixed";

/**  尺寸调整参数：原地重编码，保持源格式与路径不变（与压缩同）。 */
export type ResizeOptions = {
	/**  调整方式。 */
	mode: ResizeMode,
	/**  目标宽度；最长边模式下复用为边长。 */
	width_px: number,
	/**  目标高度；宽/最长边模式下忽略。 */
	height_px: number,
	/**  填充方式；仅固定模式生效。 */
	fill: ResizeFill,
	/**  补底颜色；仅固定 + 完整适配生效。 */
	background: ResizeBackground,
	/**  水平位置：铺满裁切的裁切锚点，或小图在画布上的贴放位。 */
	horizontal_alignment: ComicPdfHorizontalAlignment,
	/**  垂直位置：同上。 */
	vertical_alignment: ComicPdfVerticalAlignment,
	/**  仅缩小：已小于目标的不放大；铺满/拉伸下无意义，后端忽略（前端禁用）。 */
	no_upscale: boolean,
	/**  JPEG/WebP 有损质量，1-100。 */
	quality: number,
	/**  WebP 无损开关（开则忽略质量）。 */
	webp_lossless: boolean,
	/**  PNG 压缩级别，0-9。 */
	png_level: number,
};

/**  尺寸调整结果：原地覆盖后的大纲 + 处理/跳过数（与压缩同形）。 */
export type ResizeOutcome = {
	outline: ComicOutline,
	processed: number,
	skipped: number,
};

/**  尺寸调整预览：只读 `content.json` + 图片头（不全解码），返回总数、跳过数与总字节。 */
export type ResizePreview = {
	total: number,
	skipped: number,
	total_bytes: number,
};

/**  运行平台信息：经 `tauri-plugin-os` 采集，全字段必填，前端逐行展示 */
export type SystemInfo = {
	/**  操作系统平台（如 `linux` / `windows` / `macos`） */
	platform: string,
	/**  操作系统版本 */
	os_version: string,
	/**  系统架构（如 `x86_64`） */
	arch: string,
	/**  主机名 */
	hostname: string,
};

/**  命中文本段：Rust `char` 索引；中文常用字落在 BMP，前后端一致，超平面字符由前端换算。 */
export type TextSpan = {
	/**  起始字符索引（0-based）。 */
	start: number,
	/**  命中字符数。 */
	len: number,
};

/**  TXT 导出选项：章标题格式 + 卷标题格式 + 章编号方式 + 元数据清单；`items.txt` 为假时忽略。 */
export type TxtOptions = {
	/**  章标题格式。 */
	chapter_kind: TxtTitleKind,
	/**  章自定义模板；非 `custom` 时忽略。 */
	chapter_pattern: string,
	/**  卷标题格式。 */
	volume_kind: TxtTitleKind,
	/**  卷自定义模板；非 `custom` 时忽略。 */
	volume_pattern: string,
	/**  章编号方式。 */
	chapter_numbering: ChapterNumbering,
	/**  勾选的元数据字段。 */
	metadata: MetadataField[],
};

/**  TXT 标题格式：原文之外的五种全部由模板引擎渲染。 */
export type TxtTitleKind = 
/**  原文格式：完整标题行原样。 */
"original" | 
/**  阿拉伯数字。 */
"arabic" | 
/**  数字补零（宽度按全书同类最大位数，最低 2 位）。 */
"padded" | 
/**  中文小写数字。 */
"chinese_lower" | 
/**  中文大写数字。 */
"chinese_upper" | 
/**  自定义模板（`#n #N #c #C #T`，`##` 转义）。 */
"custom";

/**  可用的更新信息：只含前端展示所需字段，插件的 `Update` 句柄不出命令边界 */
export type UpdateInfo = {
	/**  远端版本号 */
	version: string,
	/**  当前版本号 */
	current_version: string,
	/**  发布说明（`latest.json` 的 `body`，可能缺失） */
	body: string | null,
};

/**  单条校验信息：`id` 沿用 epubcheck 系 message ID（如 `OPF-002`）。 */
export type ValidationMessage = {
	/**  严重度。 */
	severity: ValidationSeverity,
	/**  标准消息 ID。 */
	id: string,
	/**  人类可读描述（英文，`epubveri` 原文）。 */
	message: string,
	/**  归属文件（包内路径，无位置时为 `None`）。 */
	path: string | null,
	/**  行号（1-based，无位置时为 `None`）。 */
	line: number | null,
	/**  列号（1-based，无位置时为 `None`）。 */
	column: number | null,
};

/**  校验结果：`valid` 为假当且仅当存在 `Fatal` / `Error`。 */
export type ValidationOutcome = {
	/**  是否通过（无 `Fatal` / `Error`）。 */
	valid: boolean,
	/**  全部信息（文档顺序）。 */
	messages: ValidationMessage[],
};

/**  校验严重度：`epubveri` 五级词汇原样映射，前端按此着色与计数。 */
export type ValidationSeverity = 
/**  致命：校验中途停止。 */
"fatal" | 
/**  错误：判无效。 */
"error" | 
/**  警告：上报但不判无效。 */
"warning" | 
/**  信息：中性事实。 */
"info" | 
/**  建议：特性使用提示，永不判无效。 */
"usage";

/**  卷大纲：右栏识别结果的只读条目。 */
export type VolumeOutline = {
	/**  卷标题；无标题卷为 `None`，前端回落“未分卷”。 */
	title: string | null,
	/**  卷内章节（含完整标题与正文字数）。 */
	chapters: ChapterOutline[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

